export function drawAnimationStateView(editor){const n=machine(editor),space=editor.element.querySelector('.anim-graph-space');if(!n||!space)return;space.style.transform='translate('+editor.view.x+'px,'+editor.view.y+'px) scale('+editor.view.scale+')';editor.doc.view['machine:'+n.id]={...editor.view};const nodes=new Map(n.properties.states.map(s=>[s.id,{x:s.x,y:s.y,width:180,height:74}]));nodes.set('entry',{x:20,y:80,width:130,height:44});nodes.set('any',{x:20,y:260,width:130,height:44});const wire=(from,to,id)=>{const a=nodes.get(from),b=nodes.get(to);if(!a||!b)return '';const x=a.x+a.width,y=a.y+a.height/2,x2=b.x,y2=b.y+b.height/2,dy=from===to?-100:from==='entry'?0:18;return '<g data-as-edge="'+esc(id)+'" class="'+(editor.stateSelection===id?'selected':'')+'"><path class="anim-transition-hit" d="M '+x+' '+y+' C '+(x+90)+' '+(y+dy)+' '+(x2-90)+' '+(y2+dy)+' '+x2+' '+y2+'"/><path marker-end="url(#anim-state-arrow)" d="M '+x+' '+y+' C '+(x+90)+' '+(y+dy)+' '+(x2-90)+' '+(y2+dy)+' '+x2+' '+y2+'"/></g>';};editor.element.querySelector('.anim-graph-wires').innerHTML='<defs><marker id="anim-state-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z"/></marker></defs>'+wire('entry',n.properties.entry,'entry')+n.properties.transitions.map(t=>wire(t.from,t.to,t.id)).join('');}
export function fitAnimationStateView(editor){const n=machine(editor),canvas=editor.element.querySelector('.anim-graph-canvas'),minX=Math.min(20,...n.properties.states.map(s=>s.x)),minY=Math.min(80,...n.properties.states.map(s=>s.y)),w=Math.max(150,...n.properties.states.map(s=>s.x+180))-minX,h=Math.max(304,...n.properties.states.map(s=>s.y+74))-minY;editor.view.scale=Math.max(.2,Math.min(1,(canvas.clientWidth-50)/w,(canvas.clientHeight-50)/h));editor.view.x=25-minX*editor.view.scale;editor.view.y=25-minY*editor.view.scale;editor.draw();}
