  e.onchange=event=>{const path=event.target.dataset.animField;if(path?.includes('.conditions.')&&path.endsWith('.parameter')){editor.change(d=>{const parts=path.split('.'),key=parts.pop();let c=d;for(const part of parts)c=c[part];c[key]=event.target.value;const type=d.parameters.find(p=>p.name===c.parameter).type;c.op=['bool','trigger'].includes(type)?'true':'gt';c.value=['bool','trigger'].includes(type)?true:0;});}else parentChange(event);};
  e.onclick=event=>{const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-as-select')){editor.stateSelection=b.dataset.asSelect;editor.render();return;}const act=b.dataset.asAct;if(!act&&!b.hasAttribute('data-as-condition'))return parentClick(event);if(act==='parent'){editor.machineView=null;editor.poseScope=null;editor.view=editor.doc.view.animGraph||{x:30,y:30,scale:1};editor.render();editor.fit();return;}const {node,state,transition}=selected(editor);if(act==='pose'&&state){editor.poseScope={machine:node.id,state:state.id};editor.machineView=null;editor.selection=statePoseOutput;editor.view={x:30,y:30,scale:1};editor.render();editor.fit();return;}editor.change(d=>{const n=d.nodes.find(n=>n.id===node.id),p=n.properties;if(act==='add')editor.stateSelection=addStatePose(d,n,{x:220+p.states.length*40,y:100+p.states.length*95}).id;if(act==='entry')p.entry=state.id;if(act==='delete'){if(state)removeAnimationState(n,state.id,d);else p.transitions=p.transitions.filter(t=>t.id!==transition?.id);editor.stateSelection='';}if(act==='condition'){const first=d.parameters[0];if(!first)throw Error('파라미터를 먼저 만드세요.');p.transitions.find(t=>t.id===transition.id).conditions.push({parameter:first.name,op:['bool','trigger'].includes(first.type)?'true':'gt',value:['bool','trigger'].includes(first.type)?true:0});}if(b.hasAttribute('data-as-condition'))p.transitions.find(t=>t.id===transition.id).conditions.splice(Number(b.dataset.asCondition),1);if(['up','down'].includes(act)){const i=p.transitions.findIndex(t=>t.id===transition.id),next=i+(act==='up'?-1:1);if(next>=0&&next<p.transitions.length)[p.transitions[i],p.transitions[next]]=[p.transitions[next],p.transitions[i]];}});};
