  canvas.onpointermove=event=>{if(drag){const dx=(event.clientX-drag.x)/editor.view.scale,dy=(event.clientY-drag.y)/editor.view.scale;drag.to=[drag.from[0]+dx,drag.from[1]+dy];drag.moved=Math.hypot(dx,dy)>3;const row=e.querySelector('[data-as-node="'+drag.id+'"]');row.style.left=drag.to[0]+'px';row.style.top=drag.to[1]+'px';}if(pan){pan.moved=Math.hypot(event.clientX-pan.x,event.clientY-pan.y)>3;editor.view.x=pan.from[0]+event.clientX-pan.x;editor.view.y=pan.from[1]+event.clientY-pan.y;editor.draw();}};
  canvas.onpointerup=event=>{const target=e.ownerDocument.elementFromPoint(event.clientX,event.clientY)?.closest('[data-as-node]')?.dataset.asNode;if(wire){const from=wire;wire=null;if(target&&!['entry','any'].includes(target))editor.change(d=>{const n=d.nodes.find(n=>n.id===editor.machineView);if(from==='entry')n.properties.entry=target;else editor.stateSelection=addAnimationTransition(n,from,target,d.parameters).id;});}if(drag){const done=drag;drag=null;if(done.moved)editor.change(d=>{const s=d.nodes.find(n=>n.id===editor.machineView).properties.states.find(s=>s.id===done.id);[s.x,s.y]=done.to;});else editor.render();}if(pan){const done=pan;pan=null;if(!done.moved&&event.button===2&&!editor.hooks.running())stateMenu(editor,event);}if(canvas.hasPointerCapture(event.pointerId))canvas.releasePointerCapture(event.pointerId);};canvas.onpointercancel=()=>{wire=null;drag=null;pan=null;editor.render();};canvas.ondblclick=event=>{const state=machine(editor).properties.states.find(s=>s.id===event.target.closest('[data-as-node]')?.dataset.asNode);if(state){editor.stateSelection=state.id;e.querySelector('[data-as-select="'+state.id+'"]')?.click();e.querySelector('[data-as-act="pose"]')?.click();}};canvas.oncontextmenu=event=>event.preventDefault();
  canvas.ondragover=event=>{if(event.dataTransfer.types.includes('application/x-hb-assets')){event.preventDefault();event.dataTransfer.dropEffect='copy';}};canvas.ondrop=event=>{const raw=event.dataTransfer.getData('application/x-hb-assets');if(!raw||editor.hooks.running())return;event.preventDefault();event.stopPropagation();try{const files=JSON.parse(raw).filter(f=>['animation','spriteanimation'].includes(f.kind)),bounds=canvas.getBoundingClientRect();if(!files.length)return;editor.change(d=>{const n=d.nodes.find(n=>n.id===editor.machineView);files.forEach((f,i)=>{const state=addStatePose(d,n,{name:f.name.split('.')[0],x:(event.clientX-bounds.x-editor.view.x)/editor.view.scale+i*30,y:(event.clientY-bounds.y-editor.view.y)/editor.view.scale+i*90}),rest=d.nodes.find(node=>node.id===n.inputs[state.input]);rest.type='clip';rest.name=state.name;rest.properties={clip:f.path,loop:true,rate:1,offset:0};editor.stateSelection=state.id;});});}catch(error){editor.hooks.error(error.message);}};
