function stateMenu(editor,event){const e=editor.element,bounds=e.getBoundingClientRect();e.querySelector('.anim-node-menu')?.remove();const menu=e.ownerDocument.createElement('div');menu.className='anim-node-menu';menu.style.left=Math.max(0,Math.min(e.clientWidth-275,event.clientX-bounds.x))+'px';menu.style.top=Math.max(0,Math.min(e.clientHeight-120,event.clientY-bounds.y))+'px';menu.innerHTML='<button data-as-menu-add>'+icon('plus')+' Add State · 상태 추가</button>';e.append(menu);menu.querySelector('button').onclick=()=>{const r=e.querySelector('.anim-graph-canvas').getBoundingClientRect();editor.change(d=>{const n=d.nodes.find(n=>n.id===editor.machineView);editor.stateSelection=addStatePose(d,n,{x:(event.clientX-r.x-editor.view.x)/editor.view.scale,y:(event.clientY-r.y-editor.view.y)/editor.view.scale}).id;});};}
